function NotificationForm() {
  const [notification, setNotification] = useState("");
  const [error, setError] = useState("");
  const [submitted, setSubmitted] = useState(null);
  const radioRefs = useRef([]);

  const options = [
    { value: "email", label: "Email" },
    { value: "sms", label: "SMS" },
    { value: "push", label: "Push Notifications" },
  ];

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!notification) {
      setError("Please choose how you'd like to receive notifications.");
      setSubmitted(null);
      if (radioRefs.current[0]) radioRefs.current[0].focus();
      return;
    }
    setError("");
    const chosen = options.find((o) => o.value === notification);
    setSubmitted(chosen.label);
  };

  return (
    <form noValidate onSubmit={handleSubmit}>
      <p className="required-note">
        <span className="required-marker" aria-hidden="true">*</span> Required
      </p>
      <RadioGroupField
        legend="How do you prefer to receive notifications?"
        name="notifications"
        options={options}
        value={notification}
        onChange={(v) => { setNotification(v); if (error) setError(""); }}
        required
        helpText="Choose one option. You can change this later in settings."
        error={error}
        inputRefs={radioRefs}
      />
      <button type="submit" className="submit">Save preferences</button>
      <div aria-live="polite" aria-atomic="true">
        {submitted && (
          <p className="status success">
            Preferences saved. You'll receive notifications via {submitted}.
          </p>
        )}
      </div>
    </form>
  );
}

function App() {
  return (
    <div className="page">
      <a className="skip-link" href="#main">Skip to main content</a>
