+const { useState, useRef, useId } = React;
+
+function RadioGroupField({
+  legend,
+  name,
+  options,
+  value,
+  onChange,
+  required,
+  helpText,
+  error,
+  inputRefs,
+}) {
+  const helpId = useId();
+  const errorId = useId();
+  const describedBy = [helpText ? helpId : null, error ? errorId : null]
+    .filter(Boolean)
+    .join(" ") || undefined;
+
+  return (
+    <div className="form-field">
+      <fieldset aria-describedby={describedBy}>
+        <legend>
+          {legend}
+          {required && (
+            <span className="required-marker" aria-hidden="true">*</span>
+          )}
+        </legend>
+        {helpText && (
+          <p id={helpId} className="field-help">{helpText}</p>
+        )}
+        <div className="options">
+          {options.map((opt, i) => {
+            const id = `${name}-${opt.value}`;
+            return (
+              <label key={opt.value} className="option" htmlFor={id}>
+                <input
+                  id={id}
+                  ref={(el) => { if (inputRefs) inputRefs.current[i] = el; }}
+                  type="radio"
+                  name={name}
+                  value={opt.value}
+                  checked={value === opt.value}
+                  onChange={() => onChange(opt.value)}
+                  required={required}
+                />
+                <span className="option-label">{opt.label}</span>
+              </label>
+            );
+          })}
+        </div>
+        {error && (
+          <p id={errorId} className="field-error" role="alert">
+            Error: {error}
+          </p>
+        )}
+      </fieldset>
+    </div>
+  );
+}
+
+function NotificationForm() {
+  const [notification, setNotification] = useState("");
+  const [error, setError] = useState("");
+  const [submitted, setSubmitted] = useState(null);
+  const radioRefs = useRef([]);
+
+  const options = [
+    { value: "email", label: "Email" },
+    { value: "sms", label: "SMS" },
+    { value: "push", label: "Push Notifications" },
+  ];
+
+  const handleSubmit = (e) => {
+    e.preventDefault();
+    if (!notification) {
+      setError("Please choose how you'd like to receive notifications.");
+      setSubmitted(null);
+      if (radioRefs.current[0]) radioRefs.current[0].focus();
+      return;
+    }
+    setError("");
+    const chosen = options.find((o) => o.value === notification);
+    setSubmitted(chosen.label);
+  };
+
+  return (
+    <form noValidate onSubmit={handleSubmit}>
+      <p className="required-note">
+        <span className="required-marker" aria-hidden="true">*</span> Required
+      </p>
+      <RadioGroupField
+        legend="How do you prefer to receive notifications?"
+        name="notifications"
+        options={options}
+        value={notification}
+        onChange={(v) => { setNotification(v); if (error) setError(""); }}
+        required
+        helpText="Choose one option. You can change this later in settings."
+        error={error}
+        inputRefs={radioRefs}
+      />
+      <button type="submit" className="submit">Save preferences</button>
+      <div aria-live="polite" aria-atomic="true">
+        {submitted && (
+          <p className="status success">
+            Preferences saved. You'll receive notifications via {submitted}.
+          </p>
+        )}
+      </div>
+    </form>
+  );
+}
+
+function App() {
+  return (
+    <div className="page">
+      <a className="skip-link" href="#main">Skip to main content</a>
+      <header className="page-header">
+        <div className="brand">Notify</div>
+      </header>
+      <main id="main">
+        <section className="card" aria-labelledby="page-title">
+          <h1 id="page-title">Notification preferences</h1>
+          <p className="subtitle">
+            Tell us how you'd like to hear from us.
+          </p>
+          <NotificationForm />
+        </section>
+      </main>
+    </div>
+  );
+}
+
+const root = ReactDOM.createRoot(document.getElementById("root"));
+root.render(<App />);
+
')

